	return e != nil && e.cachedOnly
}

// entryLabel is the Registry column's label for key: entryAlias, else the URL,
// else the key itself.
func (b *RegistryBrowser) entryLabel(key string) string {
	e := b.entryFor(key)
	if e == nil {
		return key
	}
	if a := entryAlias(*e); a != "" {
		return a
	}
	if e.URL != "" {
		return e.URL
	}
	return key
