// `r` gains a group stop: narrowing to everything from one Nexus is one
// keystroke rather than one per proxy.
func TestTheResultFilterHasAGroupLevel(t *testing.T) {
	m := groupedModel(t)
	m = typeInto(t, m, "api")
	m = feed(t, m, testutil.Key("enter"))
	m = feed(t, m, stampGen(m,
		MultiRegistryTagsLoadedMsg{EntryKey: memberKey("prod", "registry.example.com", "docker-hosted"), RegistryURL: "registry.example.com", Alias: "prod/docker-hosted", Repo: "docker-hosted/api", Tags: []string{"v1"}},
		MultiRegistryTagsLoadedMsg{EntryKey: memberKey("prod", "registry.example.com", "dhi-proxy"), RegistryURL: "registry.example.com", Alias: "prod/dhi", Repo: "dhi-proxy/api", Tags: []string{"v2"}},
		MultiRegistryTagsLoadedMsg{EntryKey: "hub", RegistryURL: "docker.io", Alias: "hub", Repo: "api", Tags: []string{"latest"}},
	)...)
	b := m.registryBrowser

	m = feed(t, m, testutil.Key("r"))
	if b.registryFilter.groupSlug != "prod" {
		t.Fatalf("the first stop is %+v, want the group", b.registryFilter)
	}
	if got := len(b.tagTable.Visible()); got != 2 {
		t.Errorf("%d rows under the group filter, want both its members'", got)
	}

	// Then the individual registries, then back to everything.
	seen := map[string]bool{}
	for range len(b.entries) {
		m = feed(t, m, testutil.Key("r"))
		seen[b.registryFilter.entryKey] = true
	}
	for _, e := range b.entries {
		if !seen[e.key] {
			t.Errorf("the cycle never stopped on %s", e.key)
				cachedOnly: listsCacheOnly(reg, bySlug),
			})
			continue
		}

		b.rows = append(b.rows, pickerRow{groupSlug: reg.Slug, label: alias, entry: -1})
		for _, m := range members {
			b.rows = append(b.rows, pickerRow{label: "  " + m.Alias, entry: len(b.entries)})
			b.entries = append(b.entries, browserRegistryEntry{
				URL:         m.URL,
				Alias:       m.Alias,
				repoPrefix:  m.RepoPrefix,
				Slug:        reg.Slug,
				ParentAlias: alias,
				ParentSlug:  reg.Slug,
				parentURL:   reg.URL,
				authMode:    mode,
				cachedOnly:  config.IsNexusGroup(reg),
				key:         memberKey(reg.Slug, m.URL, m.RepoPrefix),
			})
		}
	}

	b.selectedRegs = make(map[string]bool, len(b.entries))
	for _, e := range b.entries {
		b.selectedRegs[e.key] = !deselected[e.key]
	}
}

// listsCacheOnly reports whether reg can only be listed from the cache: it is a
// Nexus group, or it declares a Nexus group as its parent (Q-B ii).
func listsCacheOnly(reg config.RegistryItem, bySlug map[string]config.RegistryItem) bool {
	if config.IsNexusGroup(reg) {
		return true
	}
	return reg.Parent != "" && config.IsNexusGroup(bySlug[reg.Parent])
}

// memberKey names one member of a group. Scoping it by the group's slug is what
// keeps two groups fronting the same repository apart, and what keeps a member
// from colliding with a standalone registry keyed on its own slug.
//
// The URL alone will not do: every member of a path-routed group answers to the
// same host now, and the prefix is the whole of what tells them apart (§3.18).
func memberKey(groupSlug, memberURL, repoPrefix string) string {
	return groupSlug + "/" + memberURL + "/" + repoPrefix

